#### 堆排序
反向遍历非叶节点建立大顶堆，再交换堆顶到尾端，缩小有效堆并下滤。建堆 O(n) 来自底层节点虽多但下滤距离短，不是 n 个节点各花 O(log n)。
<!-- interview:HeapSort -->
```cpp
void siftDown(std::vector<int> &values, std::size_t parent, std::size_t end) {
    while (parent < end / 2) {
        auto child = parent * 2 + 1;
        if (child + 1 < end && values[child + 1] > values[child])
            ++child;
        if (values[parent] >= values[child])
            return;
        std::swap(values[parent], values[child]);
        parent = child;
    }
}
void heapSort(std::vector<int> &values) {
    for (auto parent = values.size() / 2; parent > 0; --parent)
        siftDown(values, parent - 1, values.size());
    for (auto end = values.size(); end > 1; --end) {
        std::swap(values[0], values[end - 1]);
        siftDown(values, 0, end - 1);
    }
}
```

